validate_doc_update:
function (nuevo, viejo, userCtx) {
  if (nuevo._deleted) { if (userCtx.roles.indexOf('_admin') < 0) throw({ forbidden: 'Las bajas son lógicas; no se borran documentos.' }); return; }
  var tipos = ['paciente', 'consulta', 'cita', 'personal', 'medicamento'];
  if (tipos.indexOf(nuevo.type) < 0) throw({ forbidden: 'type inválido: ' + nuevo.type });
  if (nuevo._id.indexOf(nuevo.type + ':') !== 0) throw({ forbidden: 'El _id debe empezar con ' + nuevo.type + ':' });
  if (nuevo.type === 'paciente') {
    if (!nuevo.nombres || !nuevo.apellidos || !nuevo.fecha_nacimiento) throw({ forbidden: 'Paciente sin nombres, apellidos o fecha de nacimiento.' });
    if (['ACTIVO', 'BAJA'].indexOf(nuevo.estado) < 0) throw({ forbidden: 'estado inválido' });
    if (nuevo.estado === 'BAJA' && !(nuevo.baja && nuevo.baja.motivo)) throw({ forbidden: 'Una baja exige motivo.' });
  }
  if (nuevo.type === 'consulta' && viejo && viejo.cerrada) throw({ forbidden: 'Una consulta cerrada no se edita.' });
}
